import type { Story } from "./stories";

export const stories1600: Record<number, Story> = {
	1600: {
		index: 1600,
		text: `<p>Seeing as the 'efreet is an intelligent being, you hope that with reasonable words and an offer of your help you can turn away the anger of the other.</p>
<p><b>No Skill:</b> The 'efreet ignores your words as if you were a worm and unleashes just the smallest part of his fury upon you. [S1/<em>Wounded</em>]</p>
<p><b>Beguiling, Protective Talisman:</b> Your words penetrate the haze of hatred surrounding the 'efreet. He listens intently and finally he says, "I see that your intentions were not of a malicious nature and therefore I forgive you." The 'efreet vanishes in a cloud of smoke, leaving you unharmed. [D1/S1]</p>`,
	},
	1601: {
		index: 1601,
		text: `<p>Before the other, you realize that running away will not help you. Thus, you attempt another tactic and offer your services to him. The 'efreet ignores your words as if you were a worm and casts you away with a fierce blow. [S1/<em>Crippled</em>]</p>`,
	},
	1602: {
		index: 1602,
		text: `<p>Standing your ground, you offer your assistance to the other.</p>
<p><b>No Skill:</b> "A mortal who dares to speak to one of the dusky race must be a complete stranger to fear—and to sense. I respect that and leave you be." [D1/S1]</p>
<p><b>Storytelling:</b> "How can you be of aid to such a one as I?" the other demands to know. You weave a string of tales, some light-hearted and some quite dramatic: they are the stories of your own adventures. Time marches on and exhaustion thickens your tongue so that you must stop. Apprehensively, you look at the 'efreet, waiting for some reaction—and the 'efreet responds with delightful clapping. "Mortal, I have not been entertained so in a long while. Please accept this gift." He vanishes, leaving a shiny object in front of you. [D1/S1/<b>Treasure</b>]</p>`,
	},
	1603: {
		index: 1603,
		text: `<p>"You are trying to deceive me? Mortal, I am foremost of a race of deceivers and tricksters! However, your audacity amuses me and I will be less harsh on you than you deserve." [S1/<em>Wounded</em>]</p>`,
	},
	1604: {
		index: 1604,
		text: `<p>You attempt to deceive the 'efreet into believing you are not the one he seeks.</p>
<p><b>No Skill:</b> It doesn't work and the 'efreet wreaks his vengeance. [S1/<em>Crippled</em>/Have another player move you to any city]</p>
<p><b>Acting and Disguise:</b> Though you don different clothes and put on different manner, the 'efreet sees right through your performance. Still, it buys you a few extra steps, and when the lightning strikes, you are only hurt rather than killed. [S1/<em>Wounded</em>]</p>
<p><b>Protective Talisman:</b> The 'efreet swells in anger. "Are you trying to deceive me?" You smile and reply, "I don't have to," as you show him the magical artifact you have in your possession. The 'efreet's demeanor changes dramatically as he cowers and bows his head. "What is it you wish of me, master?" [D1/S1/Choice of <b>Seal Ring</b> or <b>Magic Lamp</b>]</p>`,
	},
	1605: {
		index: 1605,
		text: `<p>In the bustling bazaar you weave through people and tents until you believe you have lost your pursuer.</p>
<p><b>No Skill:</b> You are proven wrong. Very wrong. [S1/<em>Crippled</em>]</p>
<p><b>Acting and Disguise:</b> Even though you switched clothes while running through the bazaar, you are proven wrong: the 'efreet finds you! And he is not happy for the chase. He beats you, then strips you of your clothes and possessions. [S1/W-6 (Min: Beggar)/<em>Crippled</em>]</p>
<p><b>Protective Talisman:</b> You stop in an alley to catch your breath, but the 'efreet is there, waiting for you. "Vengeance is mine!" he shouts. You fumble in your robes and pull out a magical artifact. The 'efreet snarls, then disappears in a cloud of foul-smelling smoke. [D1/S1]</p>`,
	},
	1606: {
		index: 1606,
		text: `<p>The other does not listen to your offers or enticements, but instead binds you hand and foot. Several of his servants carry you away for several days across the sands. One evening, while the other slumbers, you offer to pay the guard double what he is being paid to let you go.</p>
<p><b>No Skill:</b> The guard agrees. It isn't until you've run from the site for an hour that you have no idea where you are or how to make your way back. [D1/W-1 (Min: Poor)/<em>Lost</em>]</p>
<p><b>Wilderness Lore:</b> The guard agrees, taking your money and sending you on camel back into the desert. By the time the other realizes what has happened, you have used your superior knowledge of the landscape to elude him. [D2/W-1 (Min: Poor)]</p>`,
	},
	1607: {
		index: 1607,
		text: `<p>The other binds you in place with a gesture and accuses you of foul slights, misdeeds, and crimes. You deny any involvement, but you offer to prove your good faith by collecting treasures for him.</p>
<p><b>No Skill:</b> Unfortunately, you cannot follow through on your promise. The other decides that taking your wealth from you will serve as punishment enough. [D1/W-2 (Min: Penniless)/Lose one <b>Treasure</b>]</p>
<p><b>Scholarship:</b> Though he does not trust you, he decides that your information is far too valuable to pass up. Through a combination of his funding and your knowledge, you are both able to come up with an agreeable deal. [D1/W+1 (Max: Princely)/<b>Treasure</b>]</p>
<p><b>Protective Talisman</b> (mandatory): As you speak, you can feel the other's magic slipping off you like water. As he ponders what you have said, you reach into your pocket and produce the Talisman. The other recoils from it and is gone in a blink. [D1]</p>`,
	},
	1608: {
		index: 1608,
		text: `<p>The other is of terrible mien and fouler temper, and has accused you of terrible blasphemies against his people.</p>
<p><b>No Skill:</b> You are unable to defend yourself against the charges, especially from such an august personage. You accept his judgment for your crimes. [D1/<em>Accursed</em>]</p>
<p><b>Bargaining and Evaluation:</b> You throw yourself on his mercy, saying that you know of no such blasphemy that you have committed, but will gladly help donate to the cause of spreading the word of Allah. In response to your open repentance, the other has no choice but to forgive you. [D1/<em>Respected</em>]</p>`,
	},
	1609: {
		index: 1609,
		text: `<p>The other is quite wretched and dismal. You steer clear of the other and tell all of your brief encounter. [S1]</p>`,
	},
	1610: {
		index: 1610,
		text: `<p>The other's passions have driven him to desperation, and seems to be looking to involve you with future escapades in some way. You try to avoid the situation but you keep being drawn in. Eventually you see an opportunity to trap the other and have justice brought down with a heavy hand.</p>
<p><b>No Skill:</b> You go along and assist in the ill-founded plans of the other, all the while concealing that you are going to call out the charade at the right moment. Just when the stage is set and there is no escaping the evidence, you bring in the Sultan's soldiers to arrest them both. You are praised for stopping an infidel and are rewarded. [S1/W+1 (Max: Rich)/Acting and Disguise]</p>
<p><b>Acting and Disguise:</b> You agree to help and through clever manipulations and disguises you arrange to be the one the other finds in the bed chamber. You are not alone, however, as you have also arranged for the Sultan's soldiers to be hiding in the shadows. The scoundrel is arrested and you are praised and rewarded. [W+1 (Max: Rich)/Seduction]</p>`,
	},
	1611: {
		index: 1611,
		text: `<p>You stumble upon the other in the shadows of the palace. You wish to have no part of their crazed romantic activities and quickly leave the area. Foul play is suspected the next day and a guard recalls you scurrying away from the scene. You are brought before the Sultan.</p>
<p><b>No Skill:</b> You have no defense and are branded an adulterer. You are stripped of your titles and money and banished to the wastes. [S2/W-2 (Min: Penniless)/Wilderness Lore/Lose <em>Respected</em>/Lose <b>Robe of Honor</b>/Lose <em>Sultan</em>/Lose <em>Vizier</em>]</p>
<p><b>Acting and Disguise:</b> You have no defense and are branded an adulterer. You are to be taken to the gallows to be hanged. In the night you pretend to be ill, using makeup to create blotches on your skin. None of the guards will touch you and rather than hang you, they banish you to the wastes. [S2/Wilderness Lore/Lose <em>Respected</em>/Lose <b>Robe of Honor</b>/Lose <em>Sultan</em>/Lose <em>Vizier</em>]</p>`,
	},
	1612: {
		index: 1612,
		text: `<p>You should be more careful whom you hire! Not just a cad, the other is a liar as well. Soldiers stop you and bring you both before the sultan. You are told that the other is a slave belonging to the Sultan and is a frequent runaway.</p>
<p><b>No Skill:</b> You are dismissed and must find a new vassal. Not wishing to insult the sultan, you leave. [D1/S1]</p>
<p><b>Bargaining and Evaluation:</b> You politely note to the nabobs of the court that the slave is obviously of little value due to his endless running away. They are silent, certain you will be struck down for your insolence, but the sultan laughs and says, "Your words are true and wise. I shall sell you the slave and you can deal with him." You free that slave and arrange to take his sale out of the slave's salary if he works for you. Because of your kindness, the other reforms his ways and you have a loyal vassal for many years. [D2/S1/W-1 (Min: Poor)/Courtly Graces]</p>`,
	},
	1613: {
		index: 1613,
		text: `<p>The other tells you of his many trials as you travel. You listen and are astounded by the depths of his wantonness.</p>
<p><b>No Skill:</b> You send him off to undertake the Hadj to Mecca as forgiveness, never expecting him to return. To your great surprise, he tracks you down after his pilgrimage and becomes your devoted vassal, praising you with every step. [D1/Piety/<em>Blessed</em>]</p>
<p><b>Piety</b> (mandatory): You decide that the other must make undertake the Hadj to Mecca. You decide that you must do the same and you travel together doing good works in the name of Allah. [D2/Wisdom/<em>On Pilgrimage</em>]</p>`,
	},
	1614: {
		index: 1614,
		text: `<p>You hire the other and all goes well for several weeks, despite persistent rumors which reach your ears of the other's indiscretions. One day an outraged citizen appears at your door and demands that your vassal be turned over for punishment for his crimes.</p>
<p><b>No Skill:</b> The evidence is incontrovertible. You must turn your vassal over for punishment. [D1]</p>
<p><b>Acting and Disguise:</b> You have anticipated this moment, and have concocted an alibi both clever and well-told which will definitely prove your vassal's innocence. The outraged citizen is convinced, and leaves mollified. You chastise your vassal but are glad to retain him. [D2/S1/Beguiling]</p>`,
	},
	1615: {
		index: 1615,
		text: `<p>You have a suspicion that the other is up to nefarious deeds. You decide to meet the other in the forest and teach the other a lesson or two.</p>
<p><b>No Skill:</b> You do not know much about setting traps in the forest, but you do your best to get to know the forest nonetheless. The other sees your ambush long before you spring it on him and he easily avoids you. [S1/Wilderness Lore]</p>
<p><b>Wilderness Lore:</b> You get to know the forest and prepare for a proper ambush. The stage is set for success, and you strike at just the right moment—the other not suspecting a thing. After beating the other for his misdeeds, you deliver the other to the Sultan's guards. [D1/S1/Acting and Disguise]</p>`,
	},
	1616: {
		index: 1616,
		text: `<p>Seeing the other brandishing a weapon you decide to show off your skills—and perhaps come away with some treasure. Bolstered by a recent success in combat, you feel like there is nothing and no one who can touch your skills with a blade.</p>
<p><b>No Skill:</b> You were wrong. [S1/Weapon Use/<em>Wounded</em>]</p>
<p><b>Weapon Use:</b> You easily best the other—who happens to be the son of the Sultan. You barely escape the Sultan's soldiers. They set out for the chase. [S1/<em>Pursued</em> (SOLDIER)]</p>`,
	},
	1617: {
		index: 1617,
		text: `<p>Suspicious of the armed status of the other, you carefully watch to see what deeds are being carried out. You see that the other is a thief and has amassed quite a stash of loot. You decide to wait for the other in the forest and ambush the fiend to teach a lesson—and gain some treasure.</p>
<p><b>No Skill:</b> The other is fast with the sword and skilled in the woods. There is no winning the fight and no pursuing when the other escapes. [S1/Wilderness Lore]</p>
<p><b>Wilderness Lore:</b> You get to know the forest and prepare for a proper ambush. The stage is set for success, you strike at just the right moment—the other not suspecting a thing. Among his goods, you find a most remarkable item. [D1/S1/<b>Treasure</b>]</p>`,
	},
	1618: {
		index: 1618,
		text: `<p>Obviously a wealthy personage, the other would likely travel with a great quantity of treasures and fine things. You hatch a scheme. "Oh!" you say, "Such a grand and wondrous journey on the sea I could offer you. Gather your traveling companions and your wives (and your treasures—for expenses, of course) and meet me at my fine ship. I shall show you wonders you could never dream of!" The other looks suspiciously at you and asks you to tell him which side of a ship is starboard.</p>
<p><b>No Skill:</b> You do not know and reply, "Do not quiz me! What an insult!" and storm off, determined to learn seamanship and try the scheme again someday. [Seamanship]</p>
<p><b>Seamanship:</b> You easily answer this and all of his questions. He agrees to the trip and you hire a vessel to act as your ship. Once on board, you rob him and his companions, leaving them on an island to fend for themselves. [D1/W+2 (Max: Princely)/Acting and Disguise/<b>Treasure</b>]</p>`,
	},
	1619: {
		index: 1619,
		text: `<p>You happen upon a hunting party of a wealthy personage. Spying from the woods you see that one of his porters has wandered away from protection. You see your chance for a ransom and attack.</p>
<p><b>No Skill:</b> You have no trouble sneaking up on the other, until you find yourself stuck in mud that begins slowly pulling you down. Quicksand! You cry out to the other to help you and he rescues you from nature's earthen trap. Grateful, you offer to help the other find the rest of the hunting party, and then head off on your way. [S1/Wilderness Lore]</p>
<p><b>Stealth and Stealing:</b> You greet the other with sword brandished and capture the frightened being. You have scored a lucky break as the other's owner pays a fine ransom to have him restored. [S1/W+2 (Max: Rich)]</p>`,
	},
	1620: {
		index: 1620,
		text: `<p>Kidnapping is easy enough to accomplish when your target is caught unaware. The other is not of this group and is ready to draw on you and fight. Even with your great skill you are bested by the other and you are left penniless in the alley. [D1/W-3 (Min: Penniless)/Lose one <b>Treasure</b>]</p>`,
	},
	1621: {
		index: 1621,
		text: `<p>The room you are in is palatial, furnished with objects made from the finest materials and craftsmanship. However, your eyes are drawn only to the small statue resting on a golden pedestal. Who would miss such a small item amidst this grand room? You take the statue and hide it in the folds of your clothing. [D1/S1/<b>Carnelian Idol</b>]</p>`,
	},
	1622: {
		index: 1622,
		text: `<p>The object of your desire is embedded in a strange-looking bottle. You think you can sneak away with it with ease.</p>
<p><b>No Skill, Envious</b> (mandatory): You pull on the item until it comes free with a loud "pop" and place it in the folds of your clothes. Suddenly, smoke issues forth from the bottle and forms into a large, angry 'efreet! He glowers at you and claps his hands. Next thing you know, you wake up far from your original location. [D1/S1/W=Beggar/<em>Lost</em>/Have another player move you at least four spaces away]</p>
<p><b>Scholarship:</b> Before you attempt anything, you see writing on the item—they are names of great power. You deem it wise to leave the object embedded in the bottle. [D2/S2]</p>`,
	},
	1623: {
		index: 1623,
		text: `<p>Amidst the jumble of artifacts on the merchant's table, your attention is drawn to a wonderful statue of a horseman.</p>
<p><b>No Skill:</b> Try as you might to divert the merchant's attention, he watches you like a hawk. There will be no sneaking away with this prize. [S1]</p>
<p><b>Stealth and Stealing:</b> You are engaged in conversation with the merchant when you "accidentally" drop your purse—which sounds like money when it hits the ground. The merchant immediately bends down to help pick up the purse and its contents and you take the momentary diversion to stash the artifact inside your clothes. When the purse is returned to you, you excuse yourself on the pretense of having lunch with the Vizier. [D1/S2/<b>Brass Horseman</b>]</p>`,
	},
	1624: {
		index: 1624,
		text: `<p>Only one being stands between you and the artifact of your desire. You quickly assess the other's skills and decide to rob him by trickery instead of main force, and you engage him in conversation.</p>
<p><b>No Skill:</b> The other talks incessantly; you will be driven mad if you stay any longer. You forget the artifact and rudely excuse yourself. [D1/<em>Scorned</em>]</p>
<p><b>Beguiling:</b> You are able to get in an occasional word among the other's babbling, and your tales of your adventures eventually draw his full attention. You keep him enthralled long enough to secret the artifact on your person. With this accomplished, you apologize profusely for having to leave to a prior engagement. [D2/S1/<b>Seal Ring</b>]</p>`,
	},
	1625: {
		index: 1625,
		text: `<p>The other mocks you for even attempting such a thing. "I am a legend while in my own life! You think that you can master me? Then let us see what you are made of."</p>
<p><em>Roll two dice, adding one each for Magic and Enduring Hardship:</em></p>
<p>❖ 2–7: Determination and will are not enough to overcome this terrible challenge. Before the other leaves you to lie on the ground defeated, he grants you a glimpse of true horror. [S1/<em>Insane</em>]</p>
<p>❖ 8+: After a long battle, you drain the last of the other's power. While you savor the victory, you never will be able to cleanse the memory of the battle from your mind. [Magic/<em>Insane</em>]</p>`,
	},
	1626: {
		index: 1626,
		text: `<p>The other's evil visage and rasping voice lead you to believe that he is some kind of demon, and you offer to pay for his otherworldly powers in service to your journey. Your true aim is to steal any treasures he may have.</p>
<p><b>No Skill:</b> The other follows along for a while, but proves to be a singularly useless and unimpressive villain—in fact, you begin to suspect you have misjudged the other completely. You go on your way in frustration. [S1]</p>
<p><b>Wisdom:</b> After speaking to him for a while, you realize you were mistaken about him being a demon. The wretch before you simply labors under a curse and is no menace at all (and certainly of no use to you). You are able to free the poor wretch from his misfortune and return him to his life. [D1/<em>Respected</em>]</p>`,
	},
	1627: {
		index: 1627,
		text: `<p>The other's features twist and contort until a being of blood, fire, and scale stands before you. His grim rumble of a laugh lasts what seems like an hour before he sets out the terms. He will serve you, but you must give him your soul in exchange.</p>
<p><b>No Skill:</b> You shake hands on the deal with the creature. You watch as the creature turns into inky smoke and enters your nose and mouth. You hunch over in pain as your entire head feels as though it is on fire. You pass out from the pain only to awake a short time later, twisted and changed. [Magic/Weapon Use/<em>Accursed</em>/<em>Beast Form</em>/Lose <em>Married</em>]</p>
<p><b>Piety</b> (mandatory): There is no way you could possibly accept such a deal, as it would be the greatest of affronts to Allah. You pray until the demon leaves, but feel tainted even by having attempted to hire such a beast and know that you must atone. [D2/<em>On Pilgrimage</em>]</p>`,
	},
	1628: {
		index: 1628,
		text: `<p>The other lies in a precarious situation, dangling by one hand over the edge of a deep chasm. His only chance of survival is to be pulled up by you. You offer to help if the other will aid you in your journeys. The other refuses. You use your dagger to loose his remaining hand from the rock. He plunges downward, cursing you.</p>
<p><b>No Skill:</b> You continue on your way, wasting no more time on thoughts of doomed fools. [D1]</p>
<p><b>Wilderness Lore:</b> You find your way down the path and find the corpse of the person you surrendered to Allah. You remove his belongings before continuing on your journey. [S1/W+1 (Max: Respectable)/Lose Piety]</p>`,
	},
	1629: {
		index: 1629,
		text: `<p>You met the other in the market and by subtle words encouraged them to go to a remote place, where you can get done what you need to do. However, the other got ahead of you and when you catch up, he is surrounded by a lions! If you do not act, he will surely be torn to shreds by their claws and fangs. You grab the biggest, heaviest rock that you can find and throw it at the lions. Unfortunately, you miss and strike the other in the head.</p>
<p><b>No Skill:</b> The lions momentarily stop to try to find you, but quickly return to their meal. The gruesome scene is forever burned into your memory, as you can't help but wonder what would have happened if you had never come along and tried to help. [D1/S1/<em>Grief Stricken</em>]</p>
<p><b>Wilderness Lore:</b> You manage to attract the attention of the lions in the process, but stay hidden so that they pass on. When they have moved enough distance away, you jump down and recover the unconscious form. When he comes to, he thanks you profusely for saving his life... but can't seem to remember where the bruise on his head came from... [D1/Quick Thinking]</p>`,
	},
	1630: {
		index: 1630,
		text: `<p>The other who you seek yells for your help. He is sinking into a pile of quicksand. He has enough sense not to struggle and make his demise quicker. Your instinct is to help, but then notice that the other is one who has exploited you and others in the past. You tell the other that if he swears before Allah to return all the wealth that he has obtained dishonestly, you will rescue him; and that if he does not agree, you will push him under and take his wealth to redistribute yourself.</p>
<p><b>No Skill:</b> The other's words sound bitter and false. He curses your name as you push him under. You try to find his wealth, but it seems he has taken most of it with him to his sandy grave. [S1/W+1 (Max: Rich)]</p>
<p><b>Wisdom:</b> The other agrees quickly, but you don't believe him. You place your foot on his back, and push slightly. Panicked, he says again that he will make sure, swearing to Allah. You believe him this time, and pull him out. True to his word, with you keeping a watchful eye, he returns all that he has dishonestly taken. [D1/<em>Respected</em>]</p>`,
	},
	1631: {
		index: 1631,
		text: `<p>Over the course of your adventures, you have been stymied time and again by magic. When you meet the other, you see an opportunity to advance your knowledge of the arts mystical. You prostrate yourself before the other. He bids you stand. "I have been presented with a riddle subtle and terrific, and I will suffer greatly if I cannot tease out the solution. 'Whom did Allah create from a mother but no father, and whom from a father but no mother?'"</p>
<p><b>No Skill:</b> You hem and haw, but to no avail. As the words "I do not know" fall from your lips, the other gestures sadly, and you find yourself standing on a mountaintop, shivering in the cold and angry at yourself. [S1/Enduring Hardship]</p>
<p><b>Piety:</b> You laugh at the simple riddle. "The first is Isa the Prophet, born of a virgin mother and no father; the second is Hawwa, the mother of all men, born from the flesh of Adama, the father of all men." Delight fills the face of the other, and because you have solved his problem, he agrees to teach you what you seek. It is hard going, but you persevere. [D1/Magic/<em>Determined</em>]</p>`,
	},
	1632: {
		index: 1632,
		text: `<p>As you offer your greetings to the other, he falls to his knees before you! The other tells of their own many hardships, including a curse cast by a jealous competitor. The curse can only be lifted by a blessing from one born outdoors under a new moon in midwinter.</p>
<p><b>No Skill:</b> You beg for the other not to come along because of his curse. Alas, it seems that even this brief amount of time with him has rubbed off on you. [S1/<em>Fated</em>]</p>
<p><b>Luck:</b> How can it be, but that you, yourself, were so born? You bless the other, and their curse is lifted—and you are blessed in return! [S1/<em>Blessed</em>]</p>`,
	},
	1633: {
		index: 1633,
		text: `<p>As you kneel before the other, he begs you for assistance in saving his family from a gang of ruthless bandits. You follow him into the wilderness to the bandit's lair. Once arriving at the spot, it becomes clear that the other is in league with the bandits, and there was no family at all. This was simply a lure to get you into an ambush, taking advantage of your generous nature. You strike out at the other to make him pay.</p>
<p><b>No Skill:</b> Though you are quick to gain revenge on the one who tricked you, the other bandits quickly work to incapacitate and rob you. [D1/W-1 (Min: Penniless)]</p>
<p><b>Weapon Use:</b> After taking out the one who tricked you, you proceed to use your dazzling sword skills to make short work of the amateur robbers. They flee from your skilled swordsmanship, and you recover some of the monies they have taken from previous victims. [D1/W+1 (Max: Rich)]</p>`,
	},
	1634: {
		index: 1634,
		text: `<p>You come to a city that is exceedingly poor. Lined up on every street are throngs of beggars who want some of your coin. Up ahead you see a humble looking other conjuring bits of food for some beggars. However, there is no way they can feed this many people alone, and you offer to help.</p>
<p><b>No Skill:</b> Before you can do anything, a crowd of beggars begin to gather around you. You feel parts of your clothing being torn away and you know that if you stay, you will suffer serious injury. Lashing out in defense, you are able to escape the crowd, into the arms of the other. The other pushes you behind them to keep you out of harm's way. Soon, order is restored, but you realize this is not a burden you should take on and that you should leave the city. [D1]</p>
<p><b>Scholarship:</b> While you do what you can, during a respite, you take the other aside and explain to them that by aiding the beggars in this way, they will never learn to better themselves. These people must try to help themselves, you tell the other, rather than rely solely on the kindness of others. The other agrees with you and together you leave the city. [D1/S1]</p>`,
	},
	1635: {
		index: 1635,
		text: `<p>You come to a city that is exceedingly poor. Lined up on every street are throngs of beggars who want some of your coin. You find your way through, but before you arrive at your destination, the other catches you up and humbly beseeches you for help in feeding and housing these unfortunate people here. It is a task even beyond their ability.</p>
<p><b>No Skill:</b> While you might be able to give some coins, it will not alleviate the problems this city faces. [D1]</p>
<p><b>Magic:</b> You lend your talents to the other and together you are able to create shelters in a short amount of time. With the aid of djinns and other bound spirits, together you turn the wastelands around the city into farmland, which the people are eager to work. It is a temporary relief, but one that will be appreciated by all. [D1/<em>Blessed</em>]</p>
<p><b>Magic Saddlebags:</b> You donate your treasure to the other and the people rejoice as bountiful food is made available to all. The other rewards you with treasure and knowledge. [D2/Magic/Lose <b>Magic Saddlebags</b>/<b>Book of Hidden Secrets</b>]</p>`,
	},
	1636: {
		index: 1636,
		text: `<p>You offer your services to a mighty wizard who is looking for help in his journeys. To celebrate, he throws a party in your honor. During the course of the evening, you can't help but notice that you've attracted the attentions of his daughter.</p>
<p><b>No Skill:</b> You spend your evening with the wizard's daughter, but in the morning find that she wants nothing to do with you, and you are sent away from the retinue. You swear that one day you will find her again and make her yours. [D1/<em>Love Struck</em>]</p>
<p><b>Seduction:</b> The evening is spent with the warrior's daughter, much to the wizard's chagrin. In order to escape his disapproval, you run off together. Though you have missed out on great adventures, you have found true love instead. [D2/<em>Beloved</em>]</p>`,
	},
	1637: {
		index: 1637,
		text: `<p>"I have obtained a map to one of the greatest treasures ever known," says the other. "I seek anyone who possesses great skill and knowledge to accompany me. Who's with me?" You volunteer yourself.</p>
<p><b>No Skill:</b> "You, my friend, are not quite ready for a journey of this kind. I sense great potential in you, however. I will teach you a few tricks before I depart on my journey." [Gain any one skill you do not possess]</p>
<p><b>Any 6 Skills:</b> You are able to demonstrate a wide birth of skills. You are welcomed on the journey. [Immediately move to the closest Place of Power—if two are equidistant, choose which one to enter—and have an immediate encounter]</p>`,
	},
	1638: {
		index: 1638,
		text: `<p>A sorcerer seeks test subjects for his experiments. There is promise of great reward, but it will mean risking your body to an untested spell.</p>
<p><em>You may either assist the sorcerer or not:</em></p>
<p><em>You ignore the offer:</em> You part ways and never see him again. [S1]</p>
<p><em>If you wish to assist the sorcerer, roll one die, adding one for Magic:</em></p>
<p>❖ 1: The sorcerer's spell transforms you into a strange creature. [W+2 (Max: Rich)/<em>Beast Form</em>]</p>
<p>❖ 2: The sorcerer's spell causes an unusual and unwelcome change in you. [W+2 (Max: Rich)/<em>Sex-Changed</em>]</p>
<p>❖ 3: The sorcerer's spell causes your legs to warp unnaturally. [W+2 (Max: Rich)/<em>Crippled</em>]</p>
<p>❖ 4: The sorcerer's spell causes you to become quite beautiful. [W+2 (Max: Rich)/Appearance]</p>
<p>❖ 5: The sorcerer's spell grants you the ability to endure great pain and travel long distances. [W+2 (Max: Rich)/Enduring Hardship]</p>
<p>❖ 6: The sorcerer's spell has no effect, but you learn a few things about magic along the way. [W+2 (Max: Rich)/Magic]</p>`,
	},
	1639: {
		index: 1639,
		text: `<p>The other lives by himself in a massive tower in the wilderness. You seek him out, hoping to offer him your services in exchange for aid in your quest. He greets you at the front, and invites you into his wondrous den of strange artifacts. He states that he has divined great things for you, and would be glad to help... for a price.</p>
<p><b>No Skill:</b> You have nothing to offer him, and so he places a curse upon you to force you to fulfill your destiny. [D1/Magic/<em>Under Geas</em>]</p>
<p><b>Any Treasure:</b> As a collector of magical objects, he is happy to take your treasure in exchange for knowledge. [D1/Magic/Lose a <b>Treasure</b> of your choice]</p>`,
	},
	1640: {
		index: 1640,
		text: `<p>The other rules a prosperous city, and has been known to provide patronage to those who he deems worthy. You are invited to an extravagant dinner party so that he may meet you and judge to see if he should lend his support behind you. One of the other dinner guests mentions to you in secret that the other insists on all his guests to show proper behavior at all times. Even the slightest faux pas could ruin your chances for aid.</p>
<p><b>No Skill:</b> You try your best to remain polite, but you simply lack the proper training to pass for the upper echelons of society. After a particularly embarrassing incident wherein you greeted someone with the wrong hand, you are ejected from the city. [D1/S1]</p>
<p><b>Courtly Graces:</b> You show your best side at all times, and be sure to observe all proper traditions and remain polite. The ruler is so impressed that he gives you riches with which to hire who you need to continue your journey. [D1/W+2 (Max: Princely)]</p>`,
	},
	1641: {
		index: 1641,
		text: `<p>When the other comes to town, you know he would be of value to you on your journey, and you feel you could be of great service to him as well. So you approach him about joining you. He tells you that he will not even converse anyone who he considers weak. You must prove your might to him.</p>
<p><b>No Skill:</b> You challenge him to a feat of strength.</p>
<p><em>Choose another player. You and that player roll one die, and you add one for Weapon Use:</em></p>
<p><em>If you roll higher:</em> You defeat the other and learn some of their secrets. [D2/Magic]</p>
<p><em>If the other player rolls higher, or you tie:</em> You are defeated. [S1/<em>Wounded</em>]</p>
<p><b>Seamanship:</b> You dive into the sea and swim for several hours while pulling a boat using a rope you grasp in your teeth. When you emerge, the other agrees to join up with you. He teaches you all that he knows about the arcane arts. [D2/Magic]</p>`,
	},
	1642: {
		index: 1642,
		text: `<p>The other has been confined by a fellow sorcerer to a small bottle that you happen to find sitting on the shelf of a merchant's stall. Answering your kind words, he calls upon you to be his savior. The bottle is impossible to break, but if you but pray as fervently as you can in front of him, the force of your faith can free him from his prison.</p>
<p><b>No Skill:</b> You throw yourself to the ground to pray, but the shopkeeper hears you and chases you off. When you return to the shop later, the bottle is gone. [S1]</p>
<p><b>Piety:</b> You call out for the other to go free, if it be Allah's will. The bottle glows and hums with a soft light as cracks and seams form, before shattering across the room. The other expands to normal size, and uses his power to destroy the shop where he has languished for so long. For freeing him, he offers to deliver you to anywhere you chose. [D1/Move to any city of your choice]</p>`,
	},
	1643: {
		index: 1643,
		text: `<p>The other cries out for your assistance. He has been placed under a strange curse for disturbing the wildlife here. He is slowly being turned into a tree, starting with his legs becoming rooted to the ground. You beseech whatever spirit has done this to the other to free him, for he did not know he had committed any offense.</p>
<p><b>No Skill:</b> Your fervent cries for help do no good against the curse. As the other's body finishes the transformation, he makes you swear that you will tell his family what has happened. [S2/<em>Under Geas</em>]</p>
<p><b>Wilderness Lore:</b> After you grovel for a long time, the other's situation becomes more pressing. The transformation nears completion, changing all he is into plant-life from the neck down. Seeing no choice, you dig up the roots and heft him up. You carry him as far from the cursed grove as possible. Reaching the edge of the forest, the change begins to undo itself. However, you feel a tightening in your arms: the curse has transformed itself to you! You continue to flee the area and halt your transformation as well. Though the curse does not progress, parts of your body are as gnarled as roots. [D2/<em>Crippled</em>]</p>`,
	},
	1644: {
		index: 1644,
		text: `<p>The other is chained to a pillar in the wilderness. His face lights up as you bend down before him. "My friend, I have been bound here by a foul geomancer. Will you help free me?"</p>
<p><b>No Skill:</b> You try to undo the chains, but before you realize it, many hours have slipped away. The geomancer returns and finds you, and with but a word he hurls you in a well. [S1/<em>Imprisoned</em>]</p>
<p><b>Acting and Disguise:</b> You and the other switch clothes and wait for the geomancer to return. When he does, you cry out that you have bound this innocent in your place, and that the geomancer cannot harm you while he is bound. The geomancer immediately intones a strange phrase and the chains holding the wizard grab you—freeing the true wizard instead. Caught by surprise, the geomancer quickly falls before the wizard's power. [D1/W+2 (Max: Rich)/Magic]</p>`,
	},
	1645: {
		index: 1645,
		text: `<p>You come across the other struggling to escape from twisting vines that move on their own. He cries out once before getting dragged back into the floral mass, out of sight.</p>
<p><b>No Skill:</b> You blindly strike at the vines, hoping to cut him free. Each blow cuts away some plant matter, but you cannot find the other again. [S2]</p>
<p><b>Weapon Use:</b> You cut into the vines, skillfully slicing away the mass while taking care not to touch the trapped other. After a few seconds of this, you reach in and pull him out. He takes a huge breath and praises your bravery and skill. He was a simple gardener whose plants were cursed while tending to them. Were it not for your actions, he surely would have been swallowed by the foliage. Though he has no wealth to reward you, he teaches you all that he knows about the woods. [S1/Wilderness Lore]</p>`,
	},
	1646: {
		index: 1646,
		text: `<p>A convicted criminal sits inside a glowing metal cage, taunting you. Though at first you try to ignore him, you find yourself becoming angrier and angrier at the taunts. You brandish your weapon, which does nothing to silence him.</p>
<p><b>No Skill:</b> You try to strike at him through the cage, but he merely moves aside and insults you again. After a few strikes, you accidentally hit the lock, releasing him. He thanks you, then gestures and disappears into the air. The townspeople are not happy that you freed an evil sorcerer. [S1/<em>Scorned</em>/<em>Pursued</em> (SOLDIER)]</p>
<p><b>Enduring Hardship:</b> Thinking better of it, you put away your weapon and move on. [D1/S1]</p>`,
	},
	1647: {
		index: 1647,
		text: `<p>The other sits inside a circle of rocks, arranged into a strange pattern. He laughs at you as you approach. "Only the bravest can free me from my prison. If you should succeed in striking me down, you will be rewarded with great riches. If you enter here and do not defeat me, you will take my place forever."</p>
<p><b>No Skill:</b> The scenario seems like an obvious trap, so you move on. [S1]</p>
<p><b>Quick Thinking:</b> You turn your back on the other, making as if you refuse the offer. Then you spin around and throw your sword into the other's heart while remaining outside the circle. The other screams and shrivels into nothing, the rocks changing into various precious gemstones. You collect them and move on your way. [D1/W+2 (Max: Princely)]</p>`,
	},
	1648: {
		index: 1648,
		text: `<p>You offer the other a role in your traveling retinue, promising wealth and fame. The other snorts. "What could you possibly offer me that I do not already possess?"</p>
<p><b>No Skill:</b> You offer all that you can afford. The other is impressed that you would give up all that you can in order to continue your quest. He gestures and conjures a chest full of valuables to aid you on your journeys. [D2/S2/W+2 (Max: Princely)]</p>
<p><b>Wealth: Princely or Any Treasure</b> (mandatory): You offer a generous wage, but with a gesture, the other makes all of your wealth and possessions dance in the air towards him. You are left with nothing. [D2/S3/W-6 (Min: Penniless)/Lose all <b>Treasures</b>]</p>`,
	},
	1649: {
		index: 1649,
		text: `<p>You attempt to hire the other as a personal valet. The other looks you up and down, laughs loudly, and says, "Very well, but my services do not come cheaply."</p>
<p><b>No Skill:</b> Weeks later you find that you are taking every piece of your new valet's advice and acting on it without thinking. You have become a slave to the other's whim. [D1/<em>Ensorcelled</em>]</p>
<p><b>Beguiling:</b> You are able to refuse the offer, but become hopelessly jealous of the other's power. [S1/<em>Envious</em>]</p>`,
	},
	1650: {
		index: 1650,
		text: `<p>A magician of great power lives in a vine-encrusted cavern. Though most avoid the place lest they risk the other's wrath, you dare the attempt, for the assistance of such a one would be a great aid to you.</p>
<p><b>No Skill:</b> As you make your way through the cavern entrance, the vines surrounding the opening come alive, grabbing you tightly around the neck until consciousness flees you. When you awaken, the landscape has changed dramatically: apparently you were brought to another land. You are glad to be alive. [S1/Have another player move you two spaces in any direction]</p>
<p><b>Wilderness Lore:</b> The vines around the cavern entrance seem familiar to you: you recognize their ability to grab unsuspecting victims. Luckily you also realize that by moving silently you can pass by them unmolested. Your entrance impresses the magician dwelling within. He doesn't join you, but he bestows upon you an amazing gift. [D2/S2/<b>Treasure</b>]</p>`,
	},
	1651: {
		index: 1651,
		text: `<p>You come to the calling of the other, who is a close advisor to the Sultan of this land. You are set to capture an elusive beast terrorizing the city.</p>
<p><b>No Skill:</b> You are as unsuccessful as everyone else in tracking down the beast—but you are praised for your efforts none the less. [D1]</p>
<p><b>Wilderness Lore:</b> You set traps that blend into the natural surroundings, and after only a few days—success! The Sultan rewards you as promised. [D1/W+3 (Max: Rich)/<b>Robe of Honor</b>]</p>`,
	},
	1652: {
		index: 1652,
		text: `<p>Your efforts are noble, but there is little you can offer to someone of the other's bearing and station. [S1]</p>`,
	},
	1653: {
		index: 1653,
		text: `<p>The other ranks highly in a council of magicians but is very shy when dealing with people. Knowing there is a celebration tonight at the council's meeting hall, you offer to join the other as a companion.</p>
<p><b>No Skill:</b> When the night is over the other thanks you profusely and confers a gift upon you. [S1/W+1 (Max: Rich)]</p>
<p><b>Acting and Disguise:</b> The night is made more merry when you start performing various parables and then showing your skills with various musical instruments to the delight of the guests. The other is so pleased that at the end of the night, you are showered with gifts. [D1/S2/W+2 (Max: Princely)/<b>Copper Drum</b>]</p>
<p><b>Appearance:</b> The other is the envy of all present. But one guest eyes the both of you coldly and after a moment's distraction, you are abducted by this scoundrel and transported to his lair. [Have an immediate encounter with an Angry 'Efreet (Matrix M)]</p>`,
	},
	1654: {
		index: 1654,
		text: `<p>The other approaches you late one night, lamenting his lost love. You have little patience for someone so blessed complaining about his failures in love. You strike him out of frustration.</p>
<p><b>No Skill:</b> Everyone around you is aghast at your temper. You know when the other recovers he'll want to get back at you. You run. [<em>Pursued</em>]</p>
<p><b>Appearance:</b> The other is taken aback momentarily, but then smiles. "I see you have been in my predicament, and you're right, eventually I will find the one. Let me buy you a drink." [D1]</p>`,
	},
	1655: {
		index: 1655,
		text: `<p>You are approached by the most beautiful person you have ever seen. He entreats you to join him on a journey back to his hometown. That night in the middle of the desert you find the other on top of you with yellow glowing eyes. His body changes to that of a giant snake as it constricts around you.</p>
<p><b>No Skill:</b> You struggle to get away, and in desperation, bite into the snake's body. While it recovers, you slink away into the desert, away from the beautiful terror. [S2/<em>Lost</em>/<em>Wounded</em>]</p>
<p><b>Weapon Use:</b> You cut deep into the snake's leathery hide, causing it to let out a shriek and disappear into the dark sands. [D1/S1/<em>Lost</em>]</p>`,
	},
	1656: {
		index: 1656,
		text: `<p>You are approached with an offer: a foul sorcerer's lair has been found, but no one is brave enough to try to bring the other to justice. You are not afraid, so you take the job. You sneak in. Suddenly, a light fills the room and you find yourself face to face with the most beautiful person you have ever seen—the sorcerer.</p>
<p><b>No Skill:</b> You find yourself stumbling numbly, awestruck by the beauty. He takes the opportunity to slip away into the night. [S1/<em>Love Struck</em>]</p>
<p><b>Seduction</b> (if of opposite gender): Your glib yet intriguing tongue convinces him to stay. The two of you cannot help but be entranced with one another, and you tell him of your travels. You decide to escape that night together. [D1/<em>Beloved</em>/<em>Outlaw</em>]</p>`,
	},
	1657: {
		index: 1657,
		text: `<p>The other desires to sell you a large, leather-bound, ancient tome of mysteries. The other will not allow you to open the book, but you are impressed by the embossed leather cover, cracked with age. You haggle half the day for a lower price and the other eventually accepts half of the original offer.</p>
<p><b>No Skill:</b> You purchase the book and the other disappears down a dark alley. You realize, too late, that the book is no more than an old accounting book, disguised as something more. The pages are blank. [S1]</p>
<p><b>Bargaining and Evaluation:</b> You become suspicious about the other's willingness to significantly reduce the price. Examining the book more carefully, you realize that it is actually a fake. [S2]</p>`,
	},
	1658: {
		index: 1658,
		text: `<p>A traveling shop has come to town, bringing with it all manner of exotic delights and fetishes. All the people of the town begin to spend their money with wild abandon, giving little thought to whether they can afford it or not.</p>
<p><b>No Skill:</b> You purchase a variety of fineries, haggling down all the prices. The bazaar packs up in the dark of the night, and when morning comes, you find all the "treasures" were dross and driftwood, enchanted to seem wondrous. You have been tricked into spending nearly all your money. [S1/W-2 (Min: Penniless)/Bargaining and Evaluation]</p>
<p><b>Scholarship:</b> You have read about this strange bazaar, where the mystical merchants utterly destroy a town by taking all of its wealth. You have also read that what they sell is mere trash, but they have such skill that it all appears to be treasures. Though it is hard to resist purchasing anything, you manage to set the bazaar aflame, ending the spell. [D2/S2]</p>`,
	},
	1659: {
		index: 1659,
		text: `<p>A beggar approaches you and asks for a coin. You are tired of giving away your hard-earned wealth to beggars. You offer him a job with you for which you will pay him a fair wage.</p>
<p><b>No Skill:</b> The beggar seems quite amused at your offer and turns you down. He sounds quite well-spoken for a beggar and moves on to the next person. [S1]</p>
<p><b>Acting and Disguise:</b> You recognize the beggar as a wizard in disguise. You ask him what he is doing in such a strange ruse. He explains that he wanted to test the generosity of those in the kingdom. He is amused that you would come up with such an offer. He invites you to try the disguise with him. [S1/Bargaining and Evaluation]</p>`,
	},
	1660: {
		index: 1660,
		text: `<p>As you kneel before the other, you sense ill omens hanging about him. You fear that they may encompass you as well, and beg the other for forgiveness and to be spared.</p>
<p><b>No Skill:</b> The other knows that his fate is coming and is going to face it with dignity. After accompanying you for a while, he is killed in a freak accident. Though you do not share his fate, you soon feel that an ill wind is blowing your way. [D2/<em>Accursed</em>]</p>
<p><b>Piety:</b> You pray for his fate to be changed, but preferably at a safe distance. Though you never see him again, you feel as though you have made a difference and spared him his fate. [D1/<em>Blessed</em>]</p>`,
	},
	1661: {
		index: 1661,
		text: `<p>You recognize the other from stories as a worker of dark magics, one who has been declared anathema to all civilized men. You fall to flattering him.</p>
<p><b>No Skill:</b> Before he can respond, something dark on the far horizon catches his attention. He turns and flees before saying a word. [S1]</p>
<p><b>Stealth and Stealing:</b> Mumbling and distracted, the other moves on, never noticing that you have lifted his purse—which contains wondrous things. [S1/<b>Treasure</b>]</p>`,
	},
	1662: {
		index: 1662,
		text: `<p>Too late you realize that the elixir you both just drank is poisoned. You beg the other for an antidote, but she claims there is enough for only one of you.</p>
<p><b>No Skill:</b> It seems she wanted her life to end but finally decides against your joining her—she gives the antidote to you before she expires. [D1]</p>
<p><b>Beguiling:</b> Your lamentations move the other deeply and rather than have you share her fate, she gives you the antidote, thus sealing her own fate. [D1/S1]</p>`,
	},
	1663: {
		index: 1663,
		text: `<p>Men who claim to work for the Vizier seek your assistance. In the deepest cellar of the Sultan's palace, they have found a fierce marid bound for centuries in a bottle of wine, and they have an elaborate plot to bring the marid out to them where they can command it as a drover does his flock. They need you to enter the palace disguised as a servant to retrieve the bottle—none will notice you. You agree to aid their plan to free the other.</p>
<p><b>No Skill:</b> You attempt to infiltrate the palace, but are quickly found out. You try to save yourself by telling the guards that you were trying to save the Sultan's life from the evil wizards. They are rounded up and summarily beheaded. Because of your confession you are simply placed in jail—in a deep cellar under the palace. [<em>Imprisoned</em>]</p>
<p><b>Acting and Disguise, Beguiling:</b> You are able to infiltrate the Sultan's palace with no difficulty; your humble disguise and servile bearing deflecting all notice. You make haste to the hiding-place of the enchanted bottle. Within, the marid bubbles and burns like a wildfire and you realize that no man can be trusted with such a power. Then and there you open the bottle, crying out all the names of the Most High as you declare to the evil spirit that it is free to return to its own lands but only if it never again ventures into the world of man. The marid snarls and sputters in rage beyond words, but bound by your command it fades from your sight like a sour dream. You leave the palace and then flee the town. [Magic/<em>Pursued</em> (MAGIAN)/Move one space in any direction]</p>`,
	},
	1664: {
		index: 1664,
		text: `<p>After many days lost in the wilderness, you are sorely relieved to come to a small town built around a lovely and ever-flowing spring. The people, however, are rude to the point of insult and fear haunts their every step. Comes the time for the noon prayer and you turn to the spire of the mosque, only to discover the cause of the townspeople's terror: a stream of fire arises from the tower and resolves into a vile demon! Seeing you, the evil one laughs and shouts, "Ah! Another one who still pays worship to the so-called God of Gods! Become my servant! Bow before me!"</p>
<p><b>No Skill:</b> Quaking before the power of the evil one, you feel all choice leaving you. You offer your life and soul to the monster to do with as it will. [Lose Piety/Magic/<em>Ensorcelled</em>]</p>
<p><b>Piety, Protective Talisman:</b> You fling out your left hand in contempt to the tempter. Raising your eyes to the sky, you cry out the Shahada and the Sura Al-Fatiha as proof of your faith and never do you quaver. The marid recoils as if stung by lightning, and says, "None before you has ever stood true to his creed! Truly, you have shown me that the Most High can conquer even the fear of death. I shower you with thanks for this lesson!" So saying, the monster frees the town from its spell and departs to contemplate your deeds. The townspeople in turn shower you with thanks for your assistance in freeing them from this monster. [D2/S1/W+1 (Max: Rich)/<b>Robe of Honor</b>]</p>`,
	},
	1665: {
		index: 1665,
		text: `<p>In the distance, you see the high walls of an unfamiliar city. Approaching closer, you discover an army of monsters investing the town, denying passage to all to starve out the people within. You are seized by the army and brought before their commander, the most fearsome and dreadful djinn you could ever conceive, who demands to know why you should not be immediately given over to the cooking pits. Stammering, you say that where their force and bluster have failed to break the defenses of the city, you could succeed with finesse.</p>
<p><b>No Skill:</b> After nightfall, you are clad in black and brought to the walls. One of the lesser djinn, who has arms as great as cedars, flings you over. You feel bones in your ankle break. But the guards are too busy watching the armies camped outside to notice you. Hobbling, you open the gates from the inside before any can stop you. Within seconds, the marid's army overruns the helpless city. As a reward, you are allowed to live with the horror you have wrought. [D-1/S1/<em>Wounded</em>/<em>Grief Stricken</em>]</p>
<p><b>Wilderness Lore:</b> The town is fed by a river, which the sieging army is using as a latrine. You order a dozen of the strongest demons to divert the river from its channel to flow against the walls. As the earth supporting the walls quickly turns to mud, you order half a hundred forward to dig out the foundations. As the walls collapse you seize the opportunity to flee back the way you came with some of the baggage of the demon army. [D-1/S2/W+1 (Max: Rich)]</p>`,
	},
	1666: {
		index: 1666,
		text: `<p>The other is quite old and feeble—time ravages even the people of the Dusky Land. He is in sorrow because his human spouse has vanished. The other quizzes you about the habits of humanity, still a puzzle even after all these years among our kind.</p>
<p><b>No Skill:</b> You answer all of the other's strange questions as best you can. In the end, the other's attention drifts elsewhere and you are alone again. Though you have lost some time on your journey, you are happy to have given some small comfort to such a one. [D1/S1]</p>
<p><b>Bargaining and Evaluation:</b> You agree to answer all the questions about humanity if the other will answer your question about the djinn. Gladly you spend many hours deep in conversation, and eventually something you say gives the other the key to finding the wayward spouse. The other vanishes, but not before saying a blessing on your behalf. [Magic/<em>Blessed</em>]</p>`,
	},
	1667: {
		index: 1667,
		text: `<p>In a strange village, you are surprised to find one of the djinn sobbing on a street corner! The other explains that a human had bound him into service with a terrible spell, forcing him against his nature to perform deeds of great cruelty. You swear to break the spell.</p>
<p><b>No Skill:</b> You hasten to find the evil-hearted sorcerer and berate him for forcing such a noble spirit into bondage. The wizard smiles and says, "I will gladly trade that one's freedom for yours!" Before you can respond, you find yourself bound. [D1/S1/<em>Enslaved</em>]</p>
<p><b>Courtly Graces:</b> You find the wizard, a minor prince of this land, and invite him to dine. Over a fine meal, you bring him to mind of how ignoble it is to oppress the less fortunate and how the mercy of the Most High extends even to the people of the fire. Ashamed, the other immediately releases his prisoner. [D2/S1]</p>`,
	},
	1668: {
		index: 1668,
		text: `<p>To repay a debt to one who freed him from a curse, the other is preparing a great feast for all those of this land who cannot afford to feed themselves. You offer your services to help.</p>
<p><b>No Skill:</b> You spend many a long and demanding hour, guiding the other's efforts to assure that the needs of all are met. The smiling faces of the people fill your heart with glee, and you know that nothing will deter you from your journey from now on as long as you have this memory. [D1/<em>Determined</em>]</p>
<p><b>Magic:</b> Adding your arcane skills to those of the other, all goes much smoother and faster: yet it is nothing compared to the thanks you receive by feeding the hungry. [D2/S2]</p>`,
	},
	1669: {
		index: 1669,
		text: `<p>Through an amazing set of circumstances, the other has become quite attached to you, but unfortunately, is quite the ugliest creature in this or any world. After spending some effort to spurn his advances, you become fed up and lash out. You tell him to never return, or else you will be forced to take more dramatic measures.</p>
<p><b>No Skill, Protective Talisman</b> (mandatory): He sulks away, distraught. [S1]</p>
<p><b>Appearance:</b> The other swears that the only way to be free of the memory of your lovely form is to take it from you! A few words from the djinn and you stand before your own mirror image—and the other stands before his own! You scuttle away in fear. [<em>Beast Form</em>]</p>`,
	},
	1670: {
		index: 1670,
		text: `<p>You overhear two lovers talking hurriedly. They are clearly panicked and out of breath, having run as far as they could to be away from a jealous 'efreet who kept the younger of the two as a slave of love. As they debate where to go next, the very djinn appears before them!</p>
<p><b>No Skill:</b> You scream in surprise and rush forward unthinking, drawing a blade. The djinn looks you over with bored contempt and dismisses you with a wave of the left hand. As blackness fills your mind, the djinn takes back his lover and flies away, leaving you and the heartbroken suitor otherwise unharmed. [S1/<em>Ensorcelled</em>]</p>
<p><b>Piety, Magic, Protective Talisman:</b> You command the djinn to leave the couple alone, for the Most High has dictated that man and woman should join together with their own kind. The djinn is taken aback by the force of your words and eventually sees the sense of what you say and departs. The young couple tell all they meet of your bravery. [D1/<em>Respected</em>]</p>`,
	},
	1671: {
		index: 1671,
		text: `<p>You are approached by someone quite attractive, who unbidden, takes your arm and strolls aside you, speaking words of undying love. Before you can even speak, a mighty djinn appears before you and accuses you of having stolen his lover. "Arm yourself and prepare to die!" the other cries.</p>
<p><b>No Skill:</b> Your head swimming, you draw a blade and take a stance. The djinn laughs at the sight of you, clearly outmatched, and has mercy—merely breaking your arm rather than your spine—before departing with his reluctant human prize. [D1/S1/<em>Wounded</em>]</p>
<p><b>Quick Thinking, Protective Talisman:</b> Instead of drawing your blade, you pull the beautiful human close and smother her with kisses. The djinn grows wroth, but you say, "Never does the path of true love waver, even unto death! This is my beloved, and you cannot take her from me!" The djinn is amazed by your bravery and swears to leave you to your true heart. [D1/S2/<em>Beloved</em>]</p>`,
	},
	1672: {
		index: 1672,
		text: `<p>Twisting sand storms conceal your path through the desert, and you become lost. Thirsty and sunburnt, you crawl over a dune and tumble into a lush oasis, filled with greenery, the air drenched with moisture. You hurry to the nearest stream and gulp down as much water as you can. You awaken a djinn sleeping in the water, and the other rears up, irate for his home being defiled. You offer him praises and gold as penance.</p>
<p><b>No Skill:</b> The djinn cares not for your praises, and casts you out into the desert again. When you look around back, the oasis is nowhere to be seen. [S1/<em>Lost</em>]</p>
<p><b>Wilderness Lore, Protective Talisman, Sparkling Spear:</b> The djinn is not amused, but allows you to slake your thirst before leaving his home. You wisely take as much water as you can before setting back off into the desert. [S1/W-1 (Min: Rich)]</p>`,
	},
	1673: {
		index: 1673,
		text: `<p>You hear cries and rush toward them. A crowd has gathered to where a fearsome djinn stands atop the great building, raving nonsense. The monster holds in each great hand a human child and roars with pleasure at their screams.</p>
<p><b>No Skill:</b> You cry out an offer of jewels and riches to the monster if it will simply let the children go. Amused by your choice of words, the beast lets them go—to fall to their deaths. [<em>Grief Stricken</em>]</p>
<p><b>Insane</b> (mandatory), <b>Wisdom:</b> You cry out in the same kind of nonsense that the monster speaks and catch its attention. You climb up to the rooftop, and offer the djinn worthless junk in exchange for the children. He agrees and places the children safely beside you as you toss the trinkets into the air. With a flash of fire, the djinn is gone, and you are hailed as a hero. [<b>Robe of Honor</b>]</p>`,
	},
	1674: {
		index: 1674,
		text: `<p>The other has, for reasons known only to himself, hurled you into a deep well. He cackles from the top, insisting that he will finally have his revenge on you. You do not recognize him at all and think that he has you confused with someone else. You plead for your escape and offer everything you have if he'll just let you go.</p>
<p><b>No Skill:</b> "You won't get off that easily!" he cries. He leaves you in the pit. It is several days before someone comes to your rescue, and you fall quite ill. [D1/<em>Diseased</em>]</p>
<p><b>Bargaining and Evaluation, Protective Talisman, Sparkling Spear:</b> You reiterate that you are not the one that he seeks, but if he lets you go, you'll help him find the one he is looking for and assist in his revenge. After considering the matter, the other gestures and you stand on firm ground again. Now to your task... [D2/Enduring Hardship/<em>Under Geas</em>]</p>`,
	},
	1675: {
		index: 1675,
		text: `<p>In a strange corner of a strange town, you are amazed to discover one dressed in princely robes standing by a well. By his fire-red skin and clawed hands, you can plainly tell that he is not mortal, but one of the djinn! Seeing kindness in your face, he confesses to you that he has lost his memories of who and what and where he is. Can you assist him?</p>
<p><b>No Skill:</b> You tell the other that he is clearly a djinn and that his kingdom is far away. Perhaps, you suggest, he could find a wizard who could guide him further. The other thanks you with a small gift. [D1/W+1 (Max: Rich)]</p>
<p><b>Scholarship, Magic:</b> You waste no time but immediately begin to tell the djinn all you know of the people of the smokeless fire. With each sentence, you can see recognition pass before the other's eyes until, finally, with a roar of delight, the djinn bursts into a spear of fire and ascends into the sky. You see now the way to follow to his homeland. [D1/S1/Magic/Opportunity to enter the Dusky Land]</p>`,
	},
	1676: {
		index: 1676,
		text: `<p>The other tells you that he is heading to an important party, filled with other nobles of his race. While the nobles share stories of adventure in their kingdoms, he never has anything to add. Perhaps you could tell him some of the secrets of the ways of the people of clay, that he might share them?</p>
<p><b>No Skill:</b> While you don't have much in the way of stories to share, you are able to give him a few jokes to tell. [S1]</p>
<p><b>Storytelling:</b> Feeling sorry for him, you tell him a few of your most exciting stories, and encourage him to memorize your delivery so as to impress the other party-goers. The other is so grateful that he teaches you about the ways of the people of the smokeless fire. [S1/Magic]</p>`,
	},
	1677: {
		index: 1677,
		text: `<p>A prince of the djinn walks among humans on important business of state. He seeks to capture a band of wicked djinn who are preying on mankind.</p>
<p><b>No Skill:</b> Though you volunteer, you are not much help against the marids, and the prince is distracted by the need to repeatedly save your life. Afterwards, he thanks you and gives you a small reward, but it is clear that he is not impressed with you. [S1/W+1 (Max: Respectable)]</p>
<p><b>Weapon Skill:</b> You volunteer your skill with the blade, and teach him many lessons not just of arms but of strategy and tactics. With your teachings filling his ears, he sees how to turn the monsters against each other and conquer them one by one. As he goes off, he gives you a great reward. [D2/<b>Treasure</b>]</p>`,
	},
	1678: {
		index: 1678,
		text: `<p>As you wander the streets, you meet a great prince of the djinn who wanders to and fro across the face of the earth, wishing to know more about the hearts of mankind. As he asks you many questions about your life, you spy behind him a man clad in long robes who chants under his breath.</p>
<p><b>No Skill:</b> You fumble for a warning, but are too late to stop the wizard from casting a magical net over the djinn. The noble, thinking you were part of the ambush, proclaims a terrible curse on you. [D1/<em>Accursed</em>]</p>
<p><b>Quick Thinking, Protective Talisman:</b> You call out a warning to the prince, who turns and with a simple gesture reduces the would-be wizard to a pile of ash. "That tells me more than I wished to know about the children of Adam, alas." So saying, the prince departs with a kind word... [D1/<em>Blessed</em>]</p>`,
	},
	1679: {
		index: 1679,
		text: `<p>You see a traveling show that advertises as its main attraction a terrifying monster. Snooping around, you discover that the "monster" is nothing less than a mighty djinn, held captive by many strange emblems and powerful names carved on its cage. The pain evident in the djinn's face moves you to tears and you swear to free it.</p>
<p><b>No Skill:</b> You sneak over to the cage, but are discovered. The players beat you mercilessly, but just as you lose consciousness, you break the boards on one side of the cage. When you come to, battered and bruised, the djinn is gone, as are all the players, and you have no idea where you are. [D1/S2/<em>Wounded</em>]</p>
<p><b>Enduring Hardship, Weapon Use:</b> You charge the cage and fend the handlers off long enough for the djinn to break its bonds. You gain a lesson in the powers of the djinn as you watch it make short work of its former captors. [D1/S1/Magic]</p>`,
	},
	1680: {
		index: 1680,
		text: `<p>In the wilderness, you come to the edge of a crater. Within, you see a djinn in the form of a bolt of lightning that has crashed to earth and become trapped. Writhing, it speaks in the booming voice of thunder its wish to return home to the skies, for it has fallen to earth before its time.</p>
<p><b>No Skill:</b> You try grabbing it by the tail and hurling it into the sky, but in its struggles to escape instead of flowing up, it courses down through your body. You collapse to the ground, convulsing. [S2/<em>Crippled</em>]</p>
<p><b>Scholarship, Protective Talisman:</b> You wait for a new storm to brew, and, taking up a metal pole while wielding thick leather gloves, you fling it back into the sky. As it travels upwards, it thanks you and says that one day it will strike near you in the moment you need it most. [S2/Choice of Luck or Quick Thinking]</p>`,
	},
	1681: {
		index: 1681,
		text: `<p>As you cross a stretch of empty desert, you come across a marvelous and horrid sight: a djinn bound in chains to the side of a cliff, a trickle of fresh water dripping across his forehead. Each drip sears his flesh like a brand but the demon does not cry out. Your own water skins are nearly empty. You ask the captive how it will reward you if you free it. The other says, "You can have all this water and more if you merely break these chains."</p>
<p><b>No Skill:</b> That is too little, for you can freely gather water from the pool at the monster's bound feet. You fill your skins and ride off. Only later do you discover that the water was tainted by the other's magic. [D1/<em>Sex-Changed</em>]</p>
<p><b>Storytelling:</b> Knowing the fate of those who bargain with devils, you reconsider. If the waters bring harm to such a creature, they must be blessed. You drink deeply of the water at the source and feel all your cares slip away. [D1/S1/Lose any status of your choice]</p>`,
	},
	1682: {
		index: 1682,
		text: `<p>The other hangs bound from pillars in a ruined temple to an ancient, false god. Clearly, whatever cruel master has done this wanted the other to suffer. He struggles upon seeing you, gesturing wildly to set him free. You say that you will cut him down, but he must reward you. The other nods his head in agreement.</p>
<p><b>No Skill:</b> You cut the chains holding him. As the shackles fall a thousand voices call out from all around, "Who was bound here, was accursed for great crimes. Now you have taken the curse upon yourself!" [D-1/S1/<em>Accursed</em>]</p>
<p><b>Bargaining and Evaluation:</b> You realize from the other's silence that here are chains invisible as well as visible. Such a great power is not to be tampered with. You turn your attention away from the creature and discover scattered around the ruins of the temple several large gems. Far better this reward than to meddle in forces beyond your ken. [D1/W+2 (Max: Rich)/Wisdom]</p>`,
	},
	1683: {
		index: 1683,
		text: `<p>Far from the eyes of civilization, you hear of a wealthy man who stages horrifying shows for the public's amusement. You arrive in the secret location to find a djinn trapped in a magical circle and an audience throwing dung and eggs at it, each missile calling forth a bellow of rage. You cannot let this monstrosity stand, so you declare that if the djinn is freed from its torment, you will stand an hour in its place. The crowd, already bored of their entertainment, call for you to enter the circle.</p>
<p><b>No Skill:</b> As soon as you enter the circle, you flee out the other side. The crowd chases you, hurling rocks and knives, many of which gash you horribly. But you soon evade your pursuers. [D1/S1/<em>Wounded</em>]</p>
<p><b>Enduring Hardship:</b> You stand in the circle, ducking the worst of the missiles, letting no word escape your lips as the crowd taunts you. After the promised hour, you are released. [D2/<em>Determined</em>]</p>`,
	},
	1684: {
		index: 1684,
		text: `<p>You come across a scholar and the other deep in debate. They dispute whether Allah has one name, infinitely many, or whether such a question can even be answered within the bounds of the world. "Learned sages," you interrupt, "I have wisdom even you lack." They pause. You launch into a torrent of parlor tricks (starting with the ever popular "there's a coin behind your ear!") and simple jokes.</p>
<p><b>No Skill:</b> You are met only by deep silence. The sages are not amused by your antics and go back to their debate. [S1]</p>
<p><b>Acting and Disguise:</b> They are mightily amused by your show and invite you back to entertain for a greater crowd later. [S1/W+1 (Max: Respectable)]</p>`,
	},
	1685: {
		index: 1685,
		text: `<p>The other walks ahead of you through town and you follow, waiting to ensnare him in your schemes. The night sky is obscured by clouds, and you suddenly realize you are lost amongst the dunes. Words and fragments of sentences come to you as if shouted from across a great distance—the true names of angels and the false names, pieces of alchemical formulas and mathematical proofs. You race after them, certain they will bring you to the other.</p>
<p><b>No Skill:</b> You are deeply frustrated by the little bits you can hear. If only you could find their source—but dawn comes and find you no closer to wisdom, or to lands you know. [S1/<em>Lost</em>]</p>
<p><b>Wilderness Lore:</b> You know that sounds carry strangely in the desert. Closing your eyes, you let your ears be your sole guide. Eventually, you come to the wizard, deep in conversation with a looming djinn. You drink deeply of their knowledge without them ever knowing of it. [S1/Magic]</p>`,
	},
	1686: {
		index: 1686,
		text: `<p>On a street corner, one great in learning stands and begs passer-bys for the truth. You offer him a riddle about truth: "There stand before you two djinn. One always tells the truth, and the other always lies. You have need of them to answer a question, but you can only ask them each one question, so you will need to figure out which one is which on the first question. What should you ask?"</p>
<p><b>No Skill:</b> The other is baffled. He asks you what the answer is, and you reply that you do not know either, that's why you asked him. The crowd around you laughs and you go on your way. [S1]</p>
<p><b>Wisdom:</b> The philosopher does not know the answer. "You should ask one what the other will say and realize that whatever answer you receive will be the opposite of the truth." The other is delighted by this riddle and talks with you long into the night. [S1/Scholarship]</p>`,
	},
	1687: {
		index: 1687,
		text: `<p>The other cackles at your offer. "You would intend to aid me? You are an insignificant grain of sand. What could you possibly offer me?"</p>
<p><b>No Skill:</b> Try as you might, you can find nothing the other wants. In return for your presumption, the other curses you in a thousand tongues too harsh to hear. [D1/<em>Accursed</em>]</p>
<p><b>Storytelling:</b> You have nothing to offer the other except all the stories that you have heard throughout your adventures. While the other is quite powerful, he often is bored, and forces you into his service to entertain him. [D2/<em>Enslaved</em>]</p>
<p><b>Protective Talisman</b> (mandatory): You can think of nothing that you might have that the other might want. Scowling, the other vanishes with a snap of his fingers. You feel the leaden tablet in your pocket smolder briefly, then cools. From what ill fate has it protected you this time? [D1]</p>`,
	},
	1688: {
		index: 1688,
		text: `<p>You come across a lost camel, which seems to have wandered far from its owner. It is very well groomed and finely equipped; you realize its owner must be quite wealthy. You mount it and begin to ride. Before even a minute has passed, a djinn appears before you. "Foolish mortal! Why have you stolen my camel?"</p>
<p><b>No Skill:</b> You stammer an apology. You try say that you were planning on returning the camel to its owner, but you trip over your own words so badly that the djinn will hear none of it. He gestures, and suddenly you are far away. [S1/<em>Lost</em>/Have another player move you four spaces in any direction]</p>
<p><b>Courtly Graces, Protective Talisman:</b> Without pausing even a heartbeat, you dismount and kneel before the towering form. "Your most humble servant am I. I found your camel wandering, lost and wild in the world. I rode it to bring it back to you before it could fall into harm." The other ponders your words and then laughs. "I cannot tell if you are saying truth or lies, but your bravery does you great honor. Take the camel with my blessing." [S2/W+2 (Max: Rich)/Stealth and Stealing]</p>`,
	},
	1689: {
		index: 1689,
		text: `<p>The sea itself seems to be upset, churning and rising to abnormal levels. As you try to discern the patterns in the currents, a great djinn bursts out of the water before you, bellowing in rage. It wrestles with a dendan as vast as an entire island!</p>
<p><b>No Skill:</b> You can see that the djinn is losing, and you order the sailors to fire flaming arrows into the monster. But the mighty struggle kicks up great waves which swamp your boat and send you overboard. You cast up on a far away island. [S2/Have another player move you to any island space]</p>
<p><b>Seamanship:</b> Without hesitation, you cry out in your loudest voice. The lore of the sea has served you well—the very instant that the dendan hears your cry, it perishes. The djinn laughs in triumph and skates away across the ocean. You quickly set to rendering the body of the fallen monster. [D1/S1/W+2 (Max: Rich)/<b>Dendan Oil</b>]</p>`,
	},
	1690: {
		index: 1690,
		text: `<p>The other radiates power and might. You think your only chance is to seize the initiative and run him through before he can react.</p>
<p><b>No Skill:</b> You draw your weapon and run at the other, hacking wildly at his gigantic form. A few seconds of attacking madly you realize that the other is not affected in the least by your strikes, and is simply waiting patiently for you to stop. You look up into his face, and he crushes you beneath his mighty foot before continuing on. [S2/<em>Wounded</em>]</p>
<p><b>Quick Thinking:</b> You charge the other! Though he towers above you, you run between his legs, call the blessings of Allah, and slash out while not ceasing to run. Behind you, you hear a cry of pain and a large "thud" of something collapsing to the ground. You do not, however, take the opportunity to look back. You keep on running and hope for the best. [S3]</p>
<p><b>Protective Talisman, Sparkling Spear:</b> The magics you command are great, great enough to protect you from the worst of the foul marid's curses. Still, when you realize the might of the other, you find it the better part of valor to retreat rather than test the very limits of your magic. [S1]</p>`,
	},
	1691: {
		index: 1691,
		text: `<p>You have come face to face with an enormous foe who commands demonic magics and terrible strength. You have no chance to defeat him but cling instead to the hope that one good strike will disorient him enough so that you can make your escape. You aim low with your blow and pray for the best.</p>
<p><b>No Skill:</b> You strike at the other, but it is but a scratch to him. He takes great delight in taking his time toying with you, eventually leaving you for dead. [S1/Enduring Hardship/<em>Crippled</em>]</p>
<p><b>Luck, Protective Talisman:</b> You manage to strike the one spot in the marid's leg that makes it double over in pain, and you take the opportunity to run right on by. In the distance, the creature bellows your name, and you know it will return one day. [D3/<em>Pursued</em>]</p>
<p><b>Sparkling Spear:</b> You strike with the Sparkling Spear and, to your amazement, the creature withers in an instant to dust! Truly, the power of this item is great indeed! [D1/S1]</p>`,
	},
	1692: {
		index: 1692,
		text: `<p>A dread, three-headed, dozen-armed djinn stands before you. It is legendary, spoke of only in hushed tones as an unbeatable monster that has slain many men in their quest for glory.</p>
<p><b>No Skill:</b> You prepare for battle, and engage the creature. It lashes out at you with a flurry of swords like strikes of lightning. You manage to deflect many of its attacks, but you cannot even manage a single counter-stroke. As you despair of surviving, your opponent trips on its own legs and you flee without a thought. You consider yourself fortunate to escape in a single piece. [S2/<em>Wounded</em>]</p>
<p><b>Magic:</b> You see that conventional skill of arms will fail against the creature. You opt for a less subtle approach, conjuring a mighty wind to carry the demon off into the distance. You grab its treasure and flee before it returns. [D2/S2/<b>Treasure</b>]</p>
<p><b>Protective Talisman, Sparkling Spear:</b> The fury of the creature is great, but the power of the ancient magic that you command is greater still! After an epic battle, you finally emerge triumphant! [D3/S1/<b>Treasure</b>]</p>`,
	},
	1693: {
		index: 1693,
		text: `<p>The other is amused by your efforts to misdirect him. "You have entertained me, mortal, but only briefly. What will you do next?"</p>
<p><b>No Skill:</b> Other than the tricks you've already displayed, you have little else to entertain him with. You try a dance you learned as a small child, but he is not amused. Your brief diversion has spared your life, but he places a curse on you for your impudence. [D2/<em>Ensorcelled</em>]</p>
<p><b>Storytelling, Protective Talisman:</b> You have no more tricks to distract him, but you do have a number of stories to tell. You and the other fall to an evening of tales. He is enraptured for several hours before letting you go on your way. [D2]</p>`,
	},
	1694: {
		index: 1694,
		text: `<p>You have, through no fault of your own, attracted the attention of one of the mightiest of the djinn. Desperate to curry favor, you begin to spin an elaborate (and completely false) story of your quest to obtain enough wealth to pay for the dowry of your beloved, fair as moonlight and completely out of your reach.</p>
<p><b>No Skill:</b> The other laughs at your tale of hardship. "If you are so vexed by your unfulfilled desire for the one you describe," says the other, "I shall remove the problem for you!" [S2/<em>Sex-Changed</em>]</p>
<p><b>Appearance, Protective Talisman:</b> An odd smile flickers across the other's face. "I can grant you the dowry," says the other, "but you might find it hard to return to your beloved!" So saying, the other allows you a brief entry into the world beyond the world, whence you return with your arms full of gold and your memory filled with strange and unwelcome sights. [S2/W+3 (Max: Princely)/<em>Insane</em>]</p>`,
	},
	1695: {
		index: 1695,
		text: `<p>Following a map you obtained from a sorcerer, you have come by strange byways to the very palace of the Sultan of the Djinn! The other has everything anyone could ever want—wealth and power beyond mortal imagination. Though you are received with grace, you are not content, and you try to deceive those here into allowing you to take what you can carry. In your greed, you show that you are no more than a gnat to the other, and are cast back whence you came.</p>
<p><b>No Skill:</b> Thoughts of what you had and let slip away consume your every moment. [D1/S1/<em>Envious</em>]</p>
<p><b>Wisdom:</b> You realize that you were a fool; rather than chase after all that your hungers can encompass, far better to possess only the things you truly need. [D2/Piety]</p>`,
	},
	1696: {
		index: 1696,
		text: `<p>While you are exploring the veldt, you encounter an intrepid band of hunters. After breaking bread and sharing salt, you learn that they are seeking the mysterious elephant, and you convince them to allow you to join their group for a small fee.</p>
<p><b>No Skill:</b> Though you are not a knowledgeable hunter, your keen senses prove valuable to the hunters when you are the first to spot their quarry. They agree to let you travel with them for a time. [D1/W+1 (Max: Respectable)/Wilderness Lore]</p>
<p><b>Storytelling:</b> During the hunt, you entertain the band of hunters with tales of the mysterious Elephant's Graveyard. After a week, you finally see your elephant: an aged and wrinkled bull. The leader of the band decides to follow it to see if your tales are true.</p>
<p><em>Roll two dice:</em></p>
<p>❖ 2–9: If there is an Elephant's Graveyard, this bull didn't live long enough to find it. But at least you can retrieve the ivory without danger. [S1/W+1 (Max: Rich)]</p>
<p>❖ 10+: Following at a safe distance, you watch the sickly old bull stumble and fall over a cliff. Approaching the lip, you realize it is the Elephant's Graveyard! [Go to paragraph 1193]</p>`,
	},
	1697: {
		index: 1697,
		text: `<p>You are assisting a friend who is hiring helpers for an elephant hunt when, among the worker, you spy an old rival—one who stole the heart of your beloved. You swore you would get your revenge. You curtail your haggling over his wages before he can recognize you and set him up as the leader of the expedition.</p>
<p><b>No Skill:</b> When the band attempts to capture the elephant, you get your revenge. Hunting elephants is dangerous, and no one would suspect that you pushed him on purpose... Now if only your guilt could be so easily discarded. [D-1]</p>
<p><b>Acting and Disguise:</b> You send off the hunters and then don the most magnificent robes you own, and fashion a high turban with a magnificent fake gem. Satisfied that you look officious, you wait for your rival to return from the field. Presenting yourself as a Vizier of the local Sultan, you accuse him in the public square of poaching! To your delight, the local magistrate believes you, and your foe is imprisoned. You are rewarded with half the ivory he has "stolen." [D1/S1/W+1 (Max: Rich)/Beguiling]</p>`,
	},
	1698: {
		index: 1698,
		text: `<p>Having decided to try your fortune by hunting, you hire a band of sturdy-looking natives and head into the wilderness. The blessings of the Most High are with you, and after a few days you encounter a young elephant, just old enough to sport a fine pair of small tusks. Calculating quickly, you realize it would be a more valuable prize if captured alive than dead.</p>
<p><b>No Skill:</b> You try to lure the magnificent creature into a hastily built cage, but it proves too strong and canny. Panicked, the elephant lashes out, smashing the wooden beams to bits before tossing your men about and fleeing into the night. Your favorite among the men was terribly wounded, and with heavy heart you are forced to end his noble life. [D-1/S1/<em>Grief Stricken</em>]</p>
<p><b>Luck:</b> One of the natives has experience with capturing elephants, and he shows you how to construct a complex hobble. You distract the animal, and at great risk to himself, the wise native dashes in and secures the creature's legs. You present your prize as a gift to the local Sultan, who is most delighted and impressed by your skill and generosity. [D1/S1/<b>Robe of Honor</b>]</p>`,
	},
	1699: {
		index: 1699,
		text: `<p>Following a rumor of a "Kingdom of Ivory," you enter the trackless savannah. You discover a village, with walls made from the tusks of elephants. What wealth the denizens must have!</p>
<p><b>No Skill:</b> As soon as you approach the ivory-ringed village, you are seized by mighty warriors. You discover they are brutal infidels! As they prepare to sacrifice you to the elephant kept in the center of the village, an escape plan hatches in your mind. Slipping your bonds, you yank the elephant's rope free from a surprised cannibal and climb atop the beast. The elephant is so surprised by your sudden move, she tears free from her captors. Guiding her by the rope, you ride to freedom. [D1/S1/Luck]</p>
<p><b>Stealth and Stealing:</b> Acting on some vague instinct, you decide not to approach the village openly, but instead, creep through the high grass. Thank Allah for the warning! You discover that the villagers practice human sacrifice and surely would have killed you! You quickly grab some loose shards of ivory and make your escape before you are noticed. [S1/W+1 (Max: Rich)/Quick Thinking]</p>`,
	},
};
